-- Resources content for the Programs and Clocks work in Log (CLAUDE.md,
-- "Resources stay in step with the code"): Programs is the one entry point and
-- the Clocks tab is gone; the week view, the schedule editor, and the clock
-- page's timeline/ring/hour/floating-break diagram are new. The two guides that
-- described those screens are updated and one release note is added. Content
-- only — no schema.

select private.rc_release_guide(
  p_slug => 'log-read-a-clock',
  p_tool_key => 'log',
  p_title => 'Read a clock',
  p_summary => 'The timeline and ring diagrams, hours of a longer shift, floating breaks, and versions.',
  p_screen_keys => array['log.clock'],
  p_sort_order => 10,
  p_version_note => 'Updated for the clock page timeline and ring views',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open a clock from the program that airs on it: on the program's page, select "},{"type":"text","text":"Open clock","marks":[{"type":"bold"}]},{"type":"text","text":". The band at the top of a clock's page says which programs air on it and links to their schedule, so you can get back to when it airs."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Timeline and Ring"}]},{"type":"paragraph","content":[{"type":"text","text":"The diagram shows one hour of the clock. Switch between "},{"type":"text","text":"Timeline","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Ring","marks":[{"type":"bold"}]},{"type":"text","text":" at the top right of the diagram; both behave the same way."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The network's structure comes first: segments, newscasts (dark), and promos and credits. WUWF's local opportunities are marked in blue: a dashed outline for optional, solid for required."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hover over or tab to a slot to read its name, times, and length. Select a slot to fix it in the side panel and the slot list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Slots list under the diagram lists every slot; hovering or selecting a row does the same as the diagram."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Shifts longer than an hour"}]},{"type":"paragraph","content":[{"type":"text","text":"When a program airs for more than an hour, the clock repeats every hour. Use the arrows beside "},{"type":"text","text":"Hour 1 of 2","marks":[{"type":"bold"}]},{"type":"text","text":" to step through the hours. The network structure is the same in each hour, but pinned content can differ, and a small number on a local slot shows how many items are pinned for the hour you're looking at."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Floating breaks"}]},{"type":"paragraph","content":[{"type":"text","text":"A break whose position isn't fixed appears as a shaded window. A dashed edge can move and a solid edge is fixed; the darker area is always part of the break. Select it to see when it can start and end and how long it can run."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Versions"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose a version from the "},{"type":"text","text":"Version","marks":[{"type":"bold"}]},{"type":"text","text":" menu. A version can't be edited once it exists — a correction is a new version, started with "},{"type":"text","text":"+ New version","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Changing what WUWF can fill (producers)"}]},{"type":"paragraph","content":[{"type":"text","text":"Select a slot, then use the buttons in its panel: "},{"type":"text","text":"Edit eligibility","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Pin content","marks":[{"type":"bold"}]},{"type":"text","text":" on a local slot, or "},{"type":"text","text":"Mark eligible for local content","marks":[{"type":"bold"}]},{"type":"text","text":" on a network-only one. "},{"type":"text","text":"Remove","marks":[{"type":"bold"}]},{"type":"text","text":" takes a slot out of local eligibility."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-schedule-a-program',
  p_tool_key => 'log',
  p_title => 'Schedule a program',
  p_summary => 'See the week, change when a program airs, and find programs that still need a clock.',
  p_screen_keys => array['log.program', 'log.program.schedule'],
  p_sort_order => 20,
  p_version_note => 'Updated for the week view and the schedule editor',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Programs is where the schedule and every clock are reached from. Scheduling and changing a clock are producer tasks."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"See the schedule"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Week","marks":[{"type":"bold"}]},{"type":"text","text":" view shows the week as a grid, one column per day, with each program at its air time and the clock it runs on. Programs still on the shared placeholder clock are shaded amber. Select a block to see its details, then "},{"type":"text","text":"Edit schedule","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Open program","marks":[{"type":"bold"}]},{"type":"text","text":". Use Prev, Next, and Today to change the week. The "},{"type":"text","text":"List","marks":[{"type":"bold"}]},{"type":"text","text":" view shows the same programs as a table."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find what needs attention"}]},{"type":"paragraph","content":[{"type":"text","text":"In the list, "},{"type":"text","text":"Needs a clock","marks":[{"type":"bold"}]},{"type":"text","text":" shows the programs still on the placeholder clock, and "},{"type":"text","text":"Not scheduled","marks":[{"type":"bold"}]},{"type":"text","text":" shows programs with no current schedule. Clocks no program uses are listed under "},{"type":"text","text":"Unused clocks","marks":[{"type":"bold"}]},{"type":"text","text":" below the list."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Change when a program airs"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the program. Under "},{"type":"text","text":"When it airs","marks":[{"type":"bold"}]},{"type":"text","text":" each schedule shows its days and time; select "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":". A program with one schedule also has "},{"type":"text","text":"Edit schedule","marks":[{"type":"bold"}]},{"type":"text","text":" at the top."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose the days, the start time, and the length. The quick buttons set weekdays, the weekend, or every day."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set when the schedule starts and, if it stops, when it ends. Pick the clock it runs on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the preview on the right. It shows the times, the next airing, and whether another program airs at the same time on those days. An overlap is a warning; it doesn't stop you saving."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Save schedule","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Rundowns that were already generated keep the clock they were built from; a new clock applies to rundowns generated from then on."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add a schedule"}]},{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"+ Add a time","marks":[{"type":"bold"}]},{"type":"text","text":" on a program's page, choose its days, time, and clock, and save. If the clock doesn't exist yet, select "},{"type":"text","text":"Create a clock for this program","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-09-29-log-programs-and-clocks',
  p_tool_key => 'log',
  p_released_on => '2026-09-29',
  p_title => 'Programs and clocks in one place',
  p_guide_slugs => array['log-schedule-a-program', 'log-read-a-clock'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Programs is now the one place to start. The week view shows the whole schedule as a grid, and each program's page leads with when it airs, with an Edit button that opens a schedule editor with a live preview and an overlap check. A clock's page has a timeline and a ring view, a step through the hours of a longer shift, and a shaded window for a floating break. The separate Clocks tab is gone."}]}]}$body$
);
